import{_ as e,o as t,c as l,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const p=JSON.parse('{"title":"迈克·戈德堡","description":"","frontmatter":{"title":"迈克·戈德堡","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/迈克·戈德堡.md","filePath":"04_people/迈克·戈德堡.md"}'),i={name:"04_people/迈克·戈德堡.md"};function o(s,a,n,h,_,c){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="迈克·戈德堡" tabindex="-1">迈克·戈德堡 <a class="header-anchor" href="#迈克·戈德堡" aria-label="Permalink to &quot;迈克·戈德堡&quot;">​</a></h1><ul><li><strong>角色职位</strong>：伯克希尔·哈撒韦保险业务管理层</li><li><strong>与巴菲特关系</strong>：伯克希尔保险帝国的核心高管之一，负责国家赔偿保险等重要业务</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>迈克·戈德堡是伯克希尔·哈撒韦保险业务的重要管理者，尤其与国家赔偿保险公司（National Indemnity）有着深厚的渊源。国家赔偿保险是伯克希尔保险帝国的基石，正是这笔收购让巴菲特的保险+投资的商业模式得以成型。</p><p>戈德堡在伯克希尔的保险业务中扮演着关键角色。伯克希尔的保险业务是整个集团的&quot;超级引擎&quot;，为巴菲特提供了源源不断的浮动资金（float），使其能够在资本配置上拥有独特的优势。戈德堡所负责的业务板块正是这一引擎的核心组成部分。</p><p>在保险业务的日常管理中，戈德堡展现了精准的风险评估能力和稳健的承保纪律。这些特质与巴菲特对保险业务的要求高度一致——浮存金固然重要，但以合理甚至优惠的价格获取浮存金才是保险业务的核心竞争力。戈德堡的存在进一步巩固了伯克希尔在全球保险市场的领先地位。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1967年</strong>：伯克希尔收购国家赔偿保险，迈克·戈德堡进入管理层</li><li><strong>1980-1990年代</strong>：作为保险业务核心高管，参与管理National Indemnity等板块</li><li><strong>21世纪初</strong>：继续担任伯克希尔保险业务管理职务</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=迈克·戈德堡在1986年股东信中的原话">1986年：完整翻译|/01_letters/1986年/翻译</a></li><li><a href="/search.html?q=迈克·戈德堡在1987年股东信中的原话">1987年：完整翻译|/01_letters/1987年/翻译</a></li><li><a href="/search.html?q=迈克·戈德堡在1985年股东信中的原话">1985年：完整翻译|/01_letters/1985年/翻译</a></li><li><a href="/search.html?q=迈克·戈德堡在1982年股东信中的原话">1982年：完整翻译|/01_letters/1982年/翻译</a></li><li><a href="/search.html?q=迈克·戈德堡在2024年股东信中的原话">2024年：完整翻译|/01_letters/2024年/翻译</a></li></ul>',11)])])}const u=e(i,[["render",o]]);export{p as __pageData,u as default};
